export const t = (locale: Locale, key: string) => labels[locale][key] ?? extraLabels[locale][key] ?? pageLabels[locale][key] ?? featureLabels[locale][key] ?? adminLabels[locale][key] ?? notificationLabels[locale][key] ?? supportLabels[locale][key] ?? key;
export const formatDate = (date: Date, locale: Locale) => {
  if (locale === "kk") {
    const weekdays = ["жексенбі", "дүйсенбі", "сейсенбі", "сәрсенбі", "бейсенбі", "жұма", "сенбі"];
    const months = ["қаңтар", "ақпан", "наурыз", "сәуір", "мамыр", "маусым", "шілде", "тамыз", "қыркүйек", "қазан", "қараша", "желтоқсан"];
    return `${weekdays[date.getDay()]}, ${date.getDate()} ${months[date.getMonth()]}`;
  }
  return date.toLocaleDateString(locale === "ru" ? "ru-RU" : "en-US", { weekday: "long", day: "numeric", month: "long" });
};
export const formatWeekday = (date: Date, locale: Locale) => {
  if (locale === "kk") return ["Жс", "Дс", "Сс", "Ср", "Бс", "Жм", "Сб"][date.getDay()];
  return date.toLocaleDateString(locale === "ru" ? "ru-RU" : "en-US", { weekday: "short" });
};
export const localDayKey = (date: Date) => `${date.getFullYear()}-${String(date.getMonth()+1).padStart(2,"0")}-${String(date.getDate()).padStart(2,"0")}`;
